import * as T from './three.module.js';import {loadFarmer} from './farmer-rig.js?v=world8';import {createAgent,updateAgent} from './resident-ai.js?v=neighbours16';import {createFarmPet} from './farm-pets.js?v=neighbours16';import {rectBlocked} from './farm-layouts.js?v=neighbours16';
export function createFarmResidents({parent,p,plan,register,load=true}){const residents=[],pets=[],pending=[];const blocked=(x,z)=>rectBlocked(plan.blocks,x,z,.08)||(plan.fields&&Math.abs(x-plan.fields.x)<plan.fields.w/2+.5&&Math.abs(z-plan.fields.z)<plan.fields.d/2+.5);
 for(const [i,person]of plan.people.entries()){const root=new T.Group();root.name=person.name+' · '+person.role;root.position.set(p.x+5+i*2,.2,p.z+18);parent.add(root);const agent=createAgent(p.id+'-'+person.name,root.position.x,root.position.z,plan.zones.yard,{person:true,radius:person.role==='child'?.3:.42,speed:person.role==='child'?1.4:1}),record={...person,root,agent,rig:null};residents.push(record);if(load)pending.push(loadFarmer(person.variant).then(rig=>{record.rig=rig;rig.root.scale.set(person.height*person.width,person.height,person.height*.96);root.add(rig.root);rig.model.traverse(o=>{if(o.isMesh){o.castShadow=false;const mats=Array.isArray(o.material)?o.material:[o.material];if(/torso|shirt|jacket/i.test(o.name))for(const m of mats)m.color.set(['#91a2a2','#b39b8f','#b9b087','#879eab'][(i+p.id.length)%4]);}});rig.update(0,0);rig.mixer.setTime(agent.phase);register(root,{kind:'resident',farmId:p.id,residentName:person.name,role:person.role,x:agent.x,z:agent.z,approach:{x:agent.x,z:agent.z+1.5}});}).catch(e=>{record.error=e.message;console.warn('Resident unavailable:',person.name,e.message);}));}
 for(const [i,type]of ['dog','cat'].entries()){const model=createFarmPet(type,p.id.length+i),agent=createAgent(p.id+'-'+type,p.x+6+i*3,p.z+12,plan.zones.yard,{radius:type==='cat'?.28:.5,speed:type==='cat'?.85:1.5});parent.add(model.root);pets.push({type,model,agent});register(model.root,{kind:'resident',farmId:p.id,residentName:type==='dog'?'Buddy':'Miso',role:type,x:agent.x,z:agent.z,approach:{x:agent.x,z:agent.z+1}});}
 return {residents,pets,ready:Promise.allSettled(pending),update(dt,extra=[]){const peers=[...residents,...pets].map(r=>r.agent).concat(extra);for(const r of residents){const motion=updateAgent(r.agent,dt,blocked,peers);r.root.position.set(r.agent.x,.2,r.agent.z);r.root.rotation.y=r.agent.heading;const task=r.agent.mode==='work'&&r.role!=='child'?'plant':null;r.rig?.update(dt,motion.moved/dt,task);}for(const pet of pets){const motion=updateAgent(pet.agent,dt,blocked,peers);pet.model.root.position.set(pet.agent.x,.2,pet.agent.z);pet.model.root.rotation.y=pet.agent.heading;pet.model.update(dt,pet.agent,motion.moved);}}};
}
